    for n in range(ngram_range[0], ngram_range[1] + 1):
        ngram_pattern = r'(\b\w+' + r'(?:\s+\w+){' + str(n - 1) + r'}\b)(?:\s*\1){' + str(min_repeats - 1) + r',}'
